command:
// DSCT: Hide
//
// The Hide maneuver without posting a card. Select the creature that is hiding and run this.
//
// The Director is asked who was actually observing, in the same picker the Hide ability uses,
// and you end up hidden from whoever they say was not watching. Cancelling the picker cancels
// the hide.
//
// Use the Hide ability from your sheet instead if you want the card, the rules text and the
// button. This is the shortcut for a Director moving a creature along quickly.

const api = game.modules.get('draw-steel-combat-tools')?.api;
if (!api) return ui.notifications.error('Draw Steel: Combat Tools is not active.');

const token = canvas.tokens.controlled[0];
if (!token) return ui.notifications.warn('Select the creature that is hiding first.');

await api.stealth.runHide(token);
